136	struct TimelineItemDebugInfo: Identifiable, CustomStringConvertible {
137	    let id = UUID()
138	    let model: String
139	    let originalJSON: String?
140	    let latestEditJSON: String?
141	    
142	    init(model: String, originalJSON: String?, latestEditJSON: String?) {
143	        self.model = model
144	        
145	        self.originalJSON = Self.prettyJsonFormattedString(from: originalJSON)
146	        self.latestEditJSON = Self.prettyJsonFormattedString(from: latestEditJSON)
147	    }
148	    
149	    var description: String {
150	        var description = model
151	        
152	        if let originalJSON {
153	            description += "\n\n\(originalJSON)"
154	        }
155	        
156	        if let latestEditJSON {
157	            description += "\n\n\(latestEditJSON)"
158	        }
159	        
160	        return description
161	    }
162	    
163	    // MARK: - Private
164	    
165	    private static func prettyJsonFormattedString(from string: String?) -> String? {
166	        guard let string,
167	              let data = string.data(using: .utf8),
168	              let jsonDictionary = try? JSONSerialization.jsonObject(with: data, options: .mutableContainers),
169	              let jsonData = try? JSONSerialization.data(withJSONObject: jsonDictionary, options: [.prettyPrinted]) else {
170	            return nil
171	        }
172	        
173	        return String(data: jsonData, encoding: .utf8)
174	    }
175	}
