177	struct SendHandleProxy: Hashable {
178	    enum Error: Swift.Error {
179	        case sdkError(Swift.Error)
180	    }
181	    
182	    let itemID: TimelineItemIdentifier
183	    let underlyingHandle: SendHandle
184	    
185	    func resend() async -> Result<Void, Error> {
186	        do {
187	            try await underlyingHandle.tryResend()
188	            return .success(())
189	        } catch {
190	            return .failure(.sdkError(error))
191	        }
192	    }
193	    
194	    // MARK: - Hashable
195	
196	    static func == (lhs: SendHandleProxy, rhs: SendHandleProxy) -> Bool {
197	        lhs.itemID == rhs.itemID
198	    }
199	
200	    func hash(into hasher: inout Hasher) {
201	        hasher.combine(itemID)
202	    }
203	    
204	    static var mock: SendHandleProxy {
205	        .init(itemID: .event(uniqueID: .init(UUID().uuidString),
206	                             eventOrTransactionID: .eventID(UUID().uuidString)),
207	              underlyingHandle: .init(noHandle: .init()))
208	    }
209	}
