113	    private func paginateBackwardsOnLive(requestSize: UInt16) async -> Result<Void, TimelineProxyError> {
114	        MXLog.info("Paginating backwards")
115	        
116	        do {
117	            let _ = try await timeline.paginateBackwards(numEvents: requestSize)
118	            MXLog.info("Finished paginating backwards")
119	            
120	            return .success(())
