127	    /// Paginate forward or backwards using our own logic to drive the pagination state as the
128	    /// Rust subscription isn't allowed on focussed/detached timelines.
129	    private func focussedPaginate(_ direction: PaginationDirection, requestSize: UInt16) async -> Result<Void, TimelineProxyError> {
130	        let subject = switch direction {
131	        case .backwards: backPaginationStateSubject
132	        case .forwards: forwardPaginationStateSubject
133	        }
134	        
135	        // This extra check is necessary as detached timelines don't support subscribing to pagination status.
136	        guard subject.value == .idle else {
137	            return .success(())
138	        }
139	        
140	        MXLog.info("Paginating \(direction.rawValue)")
141	        subject.send(.paginating)
142	        
143	        do {
144	            let timelineEndReached = switch direction {
145	            case .backwards: try await timeline.paginateBackwards(numEvents: requestSize)
146	            case .forwards: try await timeline.paginateForwards(numEvents: requestSize)
147	            }
148	            MXLog.info("Finished paginating \(direction.rawValue)")
149	
150	            subject.send(timelineEndReached ? .endReached : .idle)
151	            return .success(())
152	        } catch {
153	            MXLog.error("Failed paginating \(direction.rawValue) with error: \(error)")
154	            subject.send(.idle)
155	            return .failure(.sdkError(error))
156	        }
157	    }
