384	    /// Send a message within a room. If `inReplyToEventID` is specified then it will be sent as a reply
385	    /// to that particular message. This works for both normal and threaded timelines with the relation and
386	    /// fallback logic being handled SDK side based on the timeline instance focus mode.
387	    func sendMessage(_ message: String,
388	                     html: String?,
389	                     inReplyToEventID: String? = nil,
390	                     intentionalMentions: IntentionalMentions) async -> Result<Void, TimelineProxyError> {
391	        if let inReplyToEventID {
392	            MXLog.info("Sending reply to eventID: \(inReplyToEventID)")
393	        } else {
394	            MXLog.info("Sending message")
395	        }
396	        
397	        let messageContent = buildMessageContentFor(message,
398	                                                    html: html,
399	                                                    intentionalMentions: intentionalMentions.toRustMentions())
400	        
401	        do {
402	            if let inReplyToEventID {
403	                try await timeline.sendReply(msg: messageContent, eventId: inReplyToEventID)
404	                MXLog.info("Finished sending reply to eventID: \(inReplyToEventID)")
405	            } else {
406	                _ = try await timeline.send(msg: messageContent)
407	                MXLog.info("Finished sending message")
408	            }
409	        } catch {
410	            if let inReplyToEventID {
411	                MXLog.error("Failed sending reply to eventID: \(inReplyToEventID) with error: \(error)")
412	            } else {
413	                MXLog.error("Failed sending message with error: \(error)")
414	            }
415	                
416	            return .failure(.sdkError(error))
417	        }
418	            
419	        return .success(())
420	    }
