547	    func buildMessageContentFor(_ message: String,
548	                                html: String?,
549	                                intentionalMentions: Mentions) -> RoomMessageEventContentWithoutRelation {
550	        let emoteSlashCommand = "/me "
551	        let isEmote: Bool = message.starts(with: emoteSlashCommand)
552	        
553	        let content: RoomMessageEventContentWithoutRelation
554	        if isEmote {
555	            let emoteMessage = String(message.dropFirst(emoteSlashCommand.count))
556	            
557	            var emoteHtml: String?
558	            if let html {
559	                emoteHtml = String(html.dropFirst(emoteSlashCommand.count))
560	            }
561	            content = buildEmoteMessageContentFor(emoteMessage, html: emoteHtml)
562	        } else {
563	            if let html {
564	                content = messageEventContentFromHtml(body: message, htmlBody: html)
565	            } else {
566	                content = messageEventContentFromMarkdown(md: message)
567	            }
568	        }
569	        return content.withMentions(mentions: intentionalMentions)
570	    }
