582	    private func subscribeToPagination() async {
583	        switch kind {
584	        case .live:
585	            let backPaginationListener = SDKListener<PaginationStatus> { [weak self] status in
586	                guard let self else {
587	                    return
588	                }
589	                
590	                switch status {
591	                case .idle(let hitStartOfTimeline):
592	                    backPaginationStateSubject.send(hitStartOfTimeline ? .endReached : .idle)
593	                case .paginating:
594	                    backPaginationStateSubject.send(.paginating)
595	                }
596	            }
597	            
598	            do {
599	                backPaginationStateObservationToken = try await timeline.subscribeToBackPaginationStatus(listener: backPaginationListener)
600	            } catch {
601	                MXLog.error("Failed to subscribe to back pagination status with error: \(error)")
602	            }
603	            forwardPaginationStateSubject.send(.endReached)
604	        case .detached, .thread:
605	            // Detached timelines don't support observation, set the initial state ourself.
606	            backPaginationStateSubject.send(.idle)
607	            forwardPaginationStateSubject.send(.idle)
608	        case .media(let presentation):
609	            backPaginationStateSubject.send(presentation == .pinnedEventsScreen ? .endReached : .idle)
610	            forwardPaginationStateSubject.send(presentation == .roomScreenDetached ? .idle : .endReached)
611	        case .pinned:
612	            backPaginationStateSubject.send(.endReached)
613	            forwardPaginationStateSubject.send(.endReached)
614	        }
615	    }
616	}
