24	/// Adds the send info to a view with the correct layout.
25	private struct TimelineItemSendInfoModifier: ViewModifier {
26	    let sendInfo: TimelineItemSendInfo
27	    let context: TimelineViewModel.Context
28	    
29	    var layout: AnyLayout {
30	        switch sendInfo.layoutType {
31	        case .horizontal(let spacing):
32	            AnyLayout(HStackLayout(alignment: .bottom, spacing: spacing))
33	        case .vertical(let spacing):
34	            AnyLayout(GridLayout(alignment: .leading, verticalSpacing: spacing))
35	        case .overlay, .hidden:
36	            AnyLayout(ZStackLayout(alignment: .bottomTrailing))
37	        }
38	    }
39	    
40	    func body(content: Content) -> some View {
41	        layout {
42	            content
43	            
44	            TimelineItemSendInfoLabel(sendInfo: sendInfo)
45	                .contentShape(.rect)
46	                // Tap gesture to avoid the message being detected as a button by VoiceOver
47	                // (and the action shows a description that is already read to the user).
48	                .onTapGesture {
49	                    guard sendInfo.status != nil else { return }
50	                    context.send(viewAction: .itemSendInfoTapped(itemID: sendInfo.itemID))
51	                }
52	        }
53	    }
54	}
