116	/// All the data needed to render a timeline item's send info label.
117	@MainActor
118	private struct TimelineItemSendInfo {
119	    enum Status {
120	        case sendingFailed
121	        case encryptionAuthenticity(EncryptionAuthenticity)
122	        case encryptionForwarder(TimelineItemKeyForwarder)
123	    }
124	    
125	    /// Describes how the content and the send info should be arranged inside a bubble
126	    enum LayoutType {
127	        case horizontal(spacing: CGFloat = 4)
128	        case vertical(spacing: CGFloat = 4)
129	        case overlay(capsuleStyle: Bool)
130	        case hidden
131	    }
132	    
133	    let itemID: TimelineItemIdentifier
134	    let localizedString: String
135	    var status: Status?
136	    let layoutType: LayoutType
137	    
138	    var foregroundStyle: Color {
139	        switch status {
140	        case .sendingFailed:
141	            .compound.textCriticalPrimary
142	        case .encryptionAuthenticity(let authenticity):
143	            authenticity.foregroundStyle
144	        case .encryptionForwarder:
145	            .compound.textSecondary
146	        case .none:
147	            .compound.textSecondary
148	        }
149	    }
150	}
