152	private extension TimelineItemSendInfo {
153	    init(timelineItem: EventBasedTimelineItemProtocol, adjustedDeliveryStatus: TimelineItemDeliveryStatus?, enableKeyShareOnInvite: Bool) {
154	        itemID = timelineItem.id
155	        localizedString = timelineItem.localizedSendInfo
156	        
157	        status = if case .sendingFailed = adjustedDeliveryStatus {
158	            .sendingFailed
159	        } else if let authenticity = timelineItem.properties.encryptionAuthenticity {
160	            .encryptionAuthenticity(authenticity)
161	        } else if enableKeyShareOnInvite, let forwarder = timelineItem.properties.encryptionForwarder {
162	            .encryptionForwarder(forwarder)
163	        } else {
164	            nil
165	        }
166	        
167	        layoutType = switch timelineItem {
168	        case is TextBasedRoomTimelineItem:
169	            .overlay(capsuleStyle: false)
170	        case let liveLocationTimelineItem as LiveLocationRoomTimelineItem:
171	            liveLocationTimelineItem.layout
172	        case let message as EventBasedMessageTimelineItemProtocol:
173	            switch message {
174	            case is ImageRoomTimelineItem, is VideoRoomTimelineItem:
175	                .overlay(capsuleStyle: !message.hasMediaCaption)
176	            case is AudioRoomTimelineItem, is FileRoomTimelineItem:
177	                // swiftlint:disable:next void_function_in_ternary
178	                message.hasMediaCaption ? .overlay(capsuleStyle: false) : .horizontal(spacing: 0) // No spacing as the content already contains it.
179	            case let locationTimelineItem as LocationRoomTimelineItem:
180	                .overlay(capsuleStyle: locationTimelineItem.content.geoURI != nil)
181	            default:
182	                .horizontal()
183	            }
184	        case is StickerRoomTimelineItem:
185	            .overlay(capsuleStyle: true)
186	        case is PollRoomTimelineItem:
187	            .vertical(spacing: 16)
188	        default:
189	            .horizontal()
190	        }
191	    }
