723	    private func sendCurrentMessage(_ message: String, html: String?, mode: ComposerMode, intentionalMentions: IntentionalMentions) async {
724	        guard !message.isEmpty else {
725	            fatalError("This message should never be empty")
726	        }
727	
728	        actionsSubject.send(.composer(action: .clear))
729	        
730	        switch mode {
731	        case .reply(let eventID, _, _):
732	            await timelineController.sendMessage(message,
733	                                                 html: html,
734	                                                 inReplyToEventID: eventID,
735	                                                 intentionalMentions: intentionalMentions)
736	        case .edit(let originalEventOrTransactionID, .default):
737	            await timelineController.edit(originalEventOrTransactionID,
738	                                          message: message,
739	                                          html: html,
740	                                          intentionalMentions: intentionalMentions)
741	        case .edit(let originalEventOrTransactionID, .addCaption),
742	             .edit(let originalEventOrTransactionID, .editCaption):
743	            await timelineController.editCaption(originalEventOrTransactionID,
744	                                                 message: message,
745	                                                 html: html,
746	                                                 intentionalMentions: intentionalMentions)
747	        case .default:
748	            switch slashCommand(message: message) {
749	            case .join:
750	                await handleJoinCommand(message: message)
751	            case .none:
752	                await timelineController.sendMessage(message,
753	                                                     html: html,
754	                                                     inReplyToEventID: nil,
755	                                                     intentionalMentions: intentionalMentions)
756	            }
757	        case .recordVoiceMessage, .previewVoiceMessage:
758	            fatalError("invalid composer mode.")
759	        }
760	        
761	        scrollToBottom()
