796	    private func buildTimelineViews(timelineItems: [RoomTimelineItemProtocol], isSwitchingTimelines: Bool = false) {
797	        var timelineItemsDictionary = OrderedDictionary<TimelineItemIdentifier.UniqueID, RoomTimelineItemViewState>()
798	        
799	        timelineItems.filter { $0 is RedactedRoomTimelineItem }.forEach { timelineItem in
800	            // Stops the audio player when a voice message is redacted.
801	            guard let playerState = mediaPlayerProvider.playerState(for: .timelineItemIdentifier(timelineItem.id)) else {
802	                return
803	            }
804	            
805	            Task { @MainActor in
806	                playerState.detachAudioPlayer()
807	                mediaPlayerProvider.unregister(audioPlayerState: playerState)
808	            }
809	        }
810	
811	        let itemsGroupedByTimelineDisplayStyle = timelineItems.chunked { current, next in
812	            canGroupItem(timelineItem: current, with: next)
813	        }
814	        
815	        for itemGroup in itemsGroupedByTimelineDisplayStyle {
816	            guard !itemGroup.isEmpty else {
817	                MXLog.error("Found empty item group")
818	                continue
819	            }
820	            
821	            if itemGroup.count == 1 {
822	                if let firstItem = itemGroup.first {
823	                    timelineItemsDictionary.updateValue(updateViewState(item: firstItem, groupStyle: .single),
824	                                                        forKey: firstItem.id.uniqueID)
825	                }
826	            } else {
827	                for (index, item) in itemGroup.enumerated() {
828	                    if index == 0 {
829	                        timelineItemsDictionary.updateValue(updateViewState(item: item, groupStyle: state.timelineKind == .pinned ? .single : .first),
830	                                                            forKey: item.id.uniqueID)
831	                    } else if index == itemGroup.count - 1 {
832	                        timelineItemsDictionary.updateValue(updateViewState(item: item, groupStyle: state.timelineKind == .pinned ? .single : .last),
833	                                                            forKey: item.id.uniqueID)
834	                    } else {
835	                        timelineItemsDictionary.updateValue(updateViewState(item: item, groupStyle: state.timelineKind == .pinned ? .single : .middle),
836	                                                            forKey: item.id.uniqueID)
837	                    }
838	                }
839	            }
840	        }
841	        
842	        if isSwitchingTimelines {
843	            state.timelineState.isSwitchingTimelines = true
844	        }
845	        
846	        state.timelineState.itemsDictionary = timelineItemsDictionary
847	    }
848	
849	    private func updateViewState(item: RoomTimelineItemProtocol, groupStyle: TimelineGroupStyle) -> RoomTimelineItemViewState {
850	        if let timelineItemViewState = state.timelineState.itemsDictionary[item.id.uniqueID] {
851	            timelineItemViewState.groupStyle = groupStyle
852	            timelineItemViewState.type = .init(item: item)
853	            return timelineItemViewState
854	        } else {
855	            return RoomTimelineItemViewState(item: item, groupStyle: groupStyle)
856	        }
857	    }
