859	    private func canGroupItem(timelineItem: RoomTimelineItemProtocol, with otherTimelineItem: RoomTimelineItemProtocol) -> Bool {
860	        if timelineItem is CollapsibleTimelineItem || otherTimelineItem is CollapsibleTimelineItem {
861	            return false
862	        }
863	        
864	        guard let eventTimelineItem = timelineItem as? EventBasedTimelineItemProtocol,
865	              let otherEventTimelineItem = otherTimelineItem as? EventBasedTimelineItemProtocol else {
866	            return false
867	        }
868	        
869	        // State events aren't rendered as messages so shouldn't be grouped.
870	        if eventTimelineItem is StateRoomTimelineItem || otherEventTimelineItem is StateRoomTimelineItem {
871	            return false
872	        }
873	        
874	        return eventTimelineItem.sender == otherEventTimelineItem.sender
875	            && eventTimelineItem.properties.reactions.isEmpty // Reactions break the grouping.
876	            && otherEventTimelineItem.timestamp.timeIntervalSince(eventTimelineItem.timestamp) < 5 * 60 // As does the passage of time.
877	    }
