385	    
386	    /// The cancellable used to update the timeline items.
387	    private var updateTimelineItemsCancellable: AnyCancellable?
388	    /// The controller is switching the `activeTimelineItemProvider`.
389	    private var isSwitchingTimelines = false
390	    
391	    /// Configures the controller to listen to `activeTimeline` for events.
392	    /// - Parameter clearExistingItems: Whether or not to clear any existing items before loading the timeline's contents.
393	    private func configureActiveTimelineItemProvider() {
394	        updateTimelineItemsCancellable = nil
395	        
396	        isSwitchingTimelines = true
397	        
398	        // Inform the world that the initial items are loading from the store
399	        paginationState = TimelinePaginationState(backward: .paginating, forward: .paginating)
400	        callbacks.send(.isLive(activeTimelineItemProvider.kind == .live))
401	        
402	        let contentSizeChangePublisher = NotificationCenter.default.publisher(for: UIContentSizeCategory.didChangeNotification)
403	        let timelineUpdates = activeTimelineItemProvider.updatePublisher.merge(with: contentSizeChangePublisher.compactMap { [weak self] _ in
404	            guard let activeTimelineProvider = self?.activeTimelineItemProvider else {
405	                return nil
406	            }
407	            
408	            return (activeTimelineProvider.itemProxies, activeTimelineProvider.paginationState)
409	        })
410	        
411	        updateTimelineItemsCancellable = Task { [weak self] in
412	            for await (items, paginationState) in timelineUpdates.values {
413	                await self?.updateTimelineItems(itemProxies: items, paginationState: paginationState)
414	            }
415	        }.asCancellable()
416	    }
417	    
418	    private func updateTimelineItems(itemProxies: [TimelineItemProxy], paginationState: TimelinePaginationState) async {
419	        let isNewTimeline = isSwitchingTimelines
420	        isSwitchingTimelines = false
421	        
422	        let isDM = roomProxy.isDirectOneToOneRoom
423	        let displayName = roomProxy.infoPublisher.value.displayName
424	        let hasPredecessor = roomProxy.predecessorRoom != nil
425	        
426	        var newTimelineItems = await Task.detached { [timelineItemFactory, activeTimeline] in
427	            var newTimelineItems = [RoomTimelineItemProtocol]()
428	            
429	            let collapsibleChunks = itemProxies.groupBy { $0.isItemCollapsible }
430	            
431	            for (index, collapsibleChunk) in collapsibleChunks.enumerated() {
432	                let isLastItem = index == collapsibleChunks.indices.last
433	                
434	                let items = collapsibleChunk.compactMap { itemProxy in
435	                    self.buildTimelineItem(for: itemProxy,
436	                                           isDM: isDM,
437	                                           hasPredecessor: hasPredecessor,
438	                                           roomDisplayName: displayName,
439	                                           timelineItemFactory: timelineItemFactory,
440	                                           activeTimeline: activeTimeline)
441	                }
442	                
443	                if items.isEmpty {
444	                    continue
445	                }
446	                
447	                if items.count == 1, let timelineItem = items.first {
448	                    // Don't show the read marker if it's the last item in the timeline
449	                    // https://github.com/matrix-org/matrix-rust-sdk/issues/1546
450	                    guard !(timelineItem is ReadMarkerRoomTimelineItem && isLastItem) else {
451	                        continue
452	                    }
453	                    
454	                    newTimelineItems.append(timelineItem)
455	                } else {
456	                    newTimelineItems.append(CollapsibleTimelineItem(items: items))
457	                }
458	            }
459	            
460	            return newTimelineItems
461	        }.value
462	        
463	        // Check if we need to add anything to the top of the timeline.
464	        switch paginationState.backward {
465	        case .paginating:
466	            newTimelineItems.insert(PaginationIndicatorRoomTimelineItem(position: .start), at: 0)
467	        case .idle, .endReached:
468	            break
469	        }
470	        
471	        switch paginationState.forward {
472	        case .paginating:
473	            newTimelineItems.insert(PaginationIndicatorRoomTimelineItem(position: .end), at: newTimelineItems.count)
474	        case .idle, .endReached:
475	            break
476	        }
477	        
478	        timelineItems = newTimelineItems
479	        
480	        callbacks.send(.updatedTimelineItems(timelineItems: newTimelineItems, isSwitchingTimelines: isNewTimeline))
481	        self.paginationState = paginationState
482	    }
