611	private extension TimelineItemProxy {
612	    var isItemCollapsible: Bool {
613	        if case let .event(eventItem) = self {
614	            switch eventItem.content {
615	            case .profileChange, .roomMembership, .state:
616	                return true
617	            default:
618	                return false
619	            }
620	        }
621	        
622	        return false
623	    }
